<?php
 namespace Pterodactyl\Console\Commands\Dezerx; use Throwable; use Illuminate\Console\Command; use Pterodactyl\Services\Dezerx\AutoAction\AutoActions; use Pterodactyl\Services\Dezerx\AutoAction\AutoActionRunner; class RunAutoActions extends Command { protected $signature = 'dezerx:run-auto-actions'; protected $description = 'Suspends or deletes every server whose auto action due date has passed.'; public function handle(AutoActionRunner $runner): int { if (!AutoActions::enabled()) { return self::SUCCESS; } $due = $runner->due(); if ($due->isEmpty()) { return self::SUCCESS; } $ran = 0; foreach ($due as $entry) { try { $outcome = $runner->handle($entry); $ran++; $this->line("Server {$entry->server_id}: {$outcome}."); } catch (Throwable $exception) { $runner->fail($entry, $exception); $this->warn("Server {$entry->server_id}: {$exception->getMessage()}"); } } $this->info("Ran $ran auto " . ($ran === 1 ? 'action.' : 'actions.')); return self::SUCCESS; } } 